/* Aufgaben des C#-Moduls. Jede Aufgabe trägt in v ihren Code: tests/cs_verify.cjs prüft ihn mit dem echten Compiler. */
const LESSONS=__CONTENT__;
const CATS=LESSONS.map(c=>[c.cat,c.title]);
const CATNAME=Object.fromEntries(CATS);
const HINT=Object.fromEntries(LESSONS.map(c=>[c.cat,c.memo]));
const STAGES=LESSONS.map((c,i)=>({...c,ch:'ch'+(i+1)}));
const SUBS=[];
function hl(code){
 const re=/(\/\/[^\n]*)|(\$?"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\])')|\b(using|namespace|class|interface|public|private|protected|static|void|int|double|decimal|string|char|bool|var|const|new|return|if|else|switch|case|default|break|continue|for|foreach|in|while|do|try|catch|finally|throw|true|false|null|this|base|override|virtual|abstract|get|set)\b|\b(\d+(?:\.\d+)?[mMfF]?)\b|\b([A-Z][A-Za-z0-9]*)\b/g;
 let out='',last=0,m;const names=['com','str','kw','num','typ'];
 while((m=re.exec(code))){out+=esc(code.slice(last,m.index));const i=[1,2,3,4,5].find(n=>m[n]!==undefined);out+='<span class="t-'+names[i-1]+'">'+esc(m[0])+'</span>';last=re.lastIndex}
 return out+esc(code.slice(last));
}
const cs=s=>'<pre class="cs" tabindex="0">'+hl(s)+'</pre>';
const ic=s=>'<code>'+esc(s)+'</code>';
const OUTFMT='Genau das eingeben, was die Konsole zeigt. Mehrere Zeilen durch ein Leerzeichen trennen.';
function out(text,code,prompt,plain,answer,why,o={}){
 return {kind:'out',scenario:text+cs(code),prompt,plain,answer:String(answer),why,fmt:o.fmt||OUTFMT,accept:o.accept,key:text+code+prompt,v:{body:code,cls:o.cls||'',input:o.input||''}};
}
function code(text,prompt,plain,answers,why,tpl,o={}){
 answers=[].concat(answers);
 return {kind:'code',scenario:text+(o.show?cs(o.show):''),prompt,plain,answer:answers[0],accept:answers,why,fmt:o.fmt||'C# so schreiben, wie es im Editor stehen würde. Leerzeichen sind egal, Groß- und Kleinschreibung nicht.',show:'<code>'+esc(answers[0])+'</code>',key:text+(o.show||'')+prompt,v:{tpl,accept:answers,cls:o.cls||''}};
}
function choice(text,snippet,prompt,plain,right,wrongs,why,o={}){
 return {...mc(prompt,right,wrongs,why),scenario:text+(snippet?cs(snippet):''),plain,key:text+snippet+prompt,v:o.v};
}
function word(text,prompt,plain,answer,accept,why){return {kind:'text',scenario:text,prompt,plain,answer,accept,why,key:text+prompt};}
function order(text,lines,prompt,plain,why,o={}){
 let idx;do{idx=shuffle(lines.map((_,i)=>i))}while(idx.every((v,i)=>v===i));
 const L='ABCDEFGH',listing=idx.map((n,i)=>L[i]+'  '+lines[n]).join('\n');
 const ans=lines.map((_,n)=>L[idx.indexOf(n)]).join('');
 return {kind:'order',scenario:text+cs(listing),prompt,plain,answer:ans,why,show:'<code>'+ans+'</code>',fmt:'Nur die Buchstaben in der richtigen Reihenfolge, z. B. BADC.',key:text+lines.join('|'),v:{body:lines.join('\n'),input:o.input||''}};
}
function S(cat,id,f){const stage=LESSONS.findIndex(c=>c.cat===cat);const label=LESSONS[stage].types.find(t=>t[0]===id)[1];SUBS.push({id,cat,label,min:stage+1,f});}
function pathCalc(lines){return '<ol class="steps-list">'+lines.map(l=>'<li>'+l+'</li>').join('')+'</ol>';}
function scenarioHtml(t){return '<div class="scenario"><strong>AUSGANGSLAGE</strong>'+t.scenario+'</div>';}
function helpHtml(t,id){return ' <span class="qhelp" tabindex="0" role="button" aria-label="Frage einfach erklärt" aria-describedby="'+id+'"><span class="qmark" aria-hidden="true">?</span><span class="qtip" role="tooltip" id="'+id+'"><strong>Einfach gesagt:</strong> '+t.plain+'</span></span>';}
