S('wenn','i_switch',()=>{const c=pick(['1','2','3','9']),m={'1':'Neu','2':'Liste','3':'Suche'};return out('Ein Menü wertet die Auswahl aus.',`string wahl = "${c}";\nswitch (wahl)\n{\n    case "1":\n        Console.WriteLine("Neu");\n        break;\n    case "2":\n        Console.WriteLine("Liste");\n        break;\n    case "3":\n        Console.WriteLine("Suche");\n        break;\n    default:\n        Console.WriteLine("Hä?");\n        break;\n}`,pre,'Welcher Fall passt zur Auswahl?',m[c]||'Hä?',m[c]?`Der Fall "${c}" passt.`:'Kein Fall passt, also läuft default.')});
S('wenn','i_op',()=>{const [t,a,tpl,sh,y]=pick([['Der Text soll nur bei genau 443 erscheinen.','==','if (port @@ 443) { }','if (port ____ 443)','== vergleicht auf Gleichheit.'],['Die Warnung soll erscheinen, wenn der Wert nicht 0 ist.','!=','if (port @@ 0) { }','if (port ____ 0)','!= prüft auf Ungleichheit.'],['Die Warnung soll bei 100 und mehr erscheinen.','>=','if (port @@ 100) { }','if (port ____ 100)','>= schließt die 100 mit ein.'],['Der Zweig soll laufen, wenn der Wert kleiner als 1024 ist.','<','if (port @@ 1024) { }','if (port ____ 1024)','< schließt 1024 selbst aus.']]);return code(t,'Welcher Operator gehört in die Lücke?','Wie drückst du diesen Vergleich aus?',a,y,'int port = 1;\n'+tpl,{show:sh,fmt:'Nur den Operator eingeben.'})});
S('wenn','i_gleich',()=>{const n=rint(1,9);return code('Der Compiler meldet: „Der Typ int kann nicht implizit in bool konvertiert werden.“','Schreibe die korrigierte erste Zeile.','Soll hier zugewiesen oder verglichen werden?',`if (x == ${n})`,'Ein einzelnes = weist zu, == vergleicht. if braucht einen bool, und x = '+n+' liefert einen int.',`int x = 1;\n@@\n{\n}`,{show:`if (x = ${n})\n{\n    Console.WriteLine("Treffer");\n}`})});
S('wenn','i_nest',()=>{const on=pick([true,false]),l=rint(50,99);return out('Ein Server wird nur geprüft, wenn er läuft.',`bool online = ${on};\nint last = ${l};\nif (online)\n{\n    if (last > 80)\n    {\n        Console.WriteLine("Überlast");\n    }\n    else\n    {\n        Console.WriteLine("Normal");\n    }\n}\nelse\n{\n    Console.WriteLine("Aus");\n}`,pre,'Prüfe erst die äußere, dann die innere Bedingung.',!on?'Aus':l>80?'Überlast':'Normal',!on?'online ist false, die innere Prüfung wird gar nicht erreicht.':`online ist true. Danach: ${l} > 80 ist ${l>80?'wahr':'falsch'}.`)});
S('wenn','i_logik',()=>{const p=pick([22,80,443,8080]),on=pick([true,false]);return out('Eine Firewall-Regel lässt nur 80 oder 443 durch, und auch nur, wenn sie aktiv ist.',`int port = ${p};\nbool aktiv = ${on};\nif (aktiv && (port == 80 || port == 443))\n{\n    Console.WriteLine("Frei");\n}\nelse\n{\n    Console.WriteLine("Gesperrt");\n}`,pre,'Beide Teile der Bedingung müssen stimmen.',on&&(p===80||p===443)?'Frei':'Gesperrt',`aktiv ist ${on?'wahr':'falsch'}, und der Port ${p===80||p===443?'passt':'passt nicht'}. && verlangt beides.`)});
S('wenn','i_text',()=>{const v=pick(['Ja','ja','JA']);return out('Eine Sicherheitsabfrage.',`string antwort = "${v}";\nif (antwort == "Ja")\n{\n    Console.WriteLine("Löschen");\n}\nelse\n{\n    Console.WriteLine("Abbruch");\n}`,pre,'Ist == bei Text streng oder großzügig?',v==='Ja'?'Löschen':'Abbruch','== vergleicht Text exakt, also auch die Groß- und Kleinschreibung.')});

