S('schleife','l_anzahl',()=>{const a=pick([0,1,2]),n=rint(4,12),st=pick([1,2]),cmp=pick(['<','<=']);let c=0;for(let i=a;cmp==='<'?i<n:i<=n;i+=st)c++;const seq=[];for(let i=a;(cmp==='<'?i<n:i<=n);i+=st)seq.push(i);return out('Die Schleife schreibt pro Durchlauf einen Punkt. Der Zähler am Ende verrät die Anzahl.',`int zaehler = 0;\nfor (int i = ${a}; i ${cmp} ${n}; i += ${st})\n{\n    zaehler++;\n}\nConsole.WriteLine(zaehler);`,'Wie oft läuft die Schleife? Gib den Wert von zaehler an.','Schreib alle Werte von i auf und zähle sie.',c,`i nimmt die Werte ${seq.join(', ')} an. Das sind ${c} Durchläufe.`)});
S('schleife','l_summe',()=>{const n=rint(3,7);let s=0;for(let i=1;i<=n;i++)s+=i;return out('Eine Schleife addiert die Portnummern 1 bis '+n+'.',`int summe = 0;\nfor (int i = 1; i <= ${n}; i++)\n{\n    summe += i;\n}\nConsole.WriteLine(summe);`,pre,'Addiere alle Werte von i.',s,Array.from({length:n},(_,i)=>i+1).join(' + ')+' = '+s+'.')});
S('schleife','l_while',()=>{const a=rint(1,3),st=rint(2,3),e=rint(8,12);const seq=[];let x=a;while(x<e){seq.push(x);x+=st}return out('Die Bedingung wird vor jedem Durchlauf geprüft.',`int x = ${a};\nwhile (x < ${e})\n{\n    Console.WriteLine(x);\n    x += ${st};\n}`,pre,'Schreibe die Werte auf, solange die Bedingung stimmt.',seq.join(' '),`x wird ${seq.join(', ')} und dann ${x}. ${x} < ${e} ist falsch, Schluss.`)});
S('schleife','l_do',()=>{const a=rint(5,9),g=rint(1,4);return pick([()=>out('Die Bedingung ist von Anfang an falsch. Aber es ist eine do-while-Schleife.',`int n = ${a};\ndo\n{\n    Console.WriteLine(n);\n    n++;\n} while (n < ${g});`,pre,'Wann wird bei do while geprüft?',a,'do while prüft erst nach dem Block. Der Block läuft also mindestens einmal.'),()=>out('Dieselbe Bedingung, aber mit while.',`int n = ${a};\nwhile (n < ${g})\n{\n    Console.WriteLine(n);\n    n++;\n}\nConsole.WriteLine("Ende");`,pre,'Wann wird bei while geprüft?','Ende','while prüft zuerst. Die Bedingung ist falsch, der Block läuft kein einziges Mal.')])()});
S('schleife','l_foreach',()=>{const a=shuffle(GER).slice(0,3);return out('Alle Geräte werden gemeldet.',`string[] geraete = { ${a.map(x=>`"${x}"`).join(', ')} };\nforeach (string g in geraete)\n{\n    Console.Write(g[0]);\n}`,'Was steht im Terminal?','g[0] ist der erste Buchstabe des aktuellen Geräts.',a.map(x=>x[0]).join(''),'foreach nimmt jedes Element der Reihe nach. g[0] liefert davon das erste Zeichen. Write bricht nicht um.',{fmt:'Genau das eingeben, was die Konsole zeigt.'})});
S('schleife','l_break',()=>{const n=rint(6,9),k=rint(2,5);return pick([()=>{const s=[];for(let i=1;i<=n;i++){if(i===k)break;s.push(i)}return out('Beim ersten kaputten Gerät wird abgebrochen.',`for (int i = 1; i <= ${n}; i++)\n{\n    if (i == ${k})\n    {\n        break;\n    }\n    Console.WriteLine(i);\n}`,pre,'Was macht break mit der gesamten Schleife?',s.join(' '),`Bei i = ${k} verlässt break die Schleife, bevor ${k} ausgegeben wird.`)},()=>{const s=[];for(let i=1;i<=n;i++){if(i===k)continue;s.push(i)}return out('Ein Gerät wird übersprungen.',`for (int i = 1; i <= ${n}; i++)\n{\n    if (i == ${k})\n    {\n        continue;\n    }\n    Console.WriteLine(i);\n}`,pre,'Was macht continue mit dem aktuellen Durchlauf?',s.join(' '),`continue springt bei i = ${k} sofort zum nächsten Durchlauf. Nur die ${k} fehlt.`)}])()});
const LE=[['int i = 0;\nwhile (i < 5)\n{\n    Console.WriteLine(i);\n}','Das Hochzählen fehlt. i bleibt immer 0.'],['for (int i = 0; i < 5; i--)\n{\n    Console.WriteLine(i);\n}','i wird kleiner statt größer und bleibt also unter 5. Sinnvoll wäre i++.'],['int i = 1;\nwhile (i != 10)\n{\n    i += 2;\n}','i wird 1, 3, 5, 7, 9, 11 und trifft die 10 nie. Die Prüfung müsste i < 10 heißen.']];
S('schleife','l_endlos',()=>{const [c,y]=pick(LE);return choice('Der Lüfter dreht hoch, das Programm hängt.',c,'Was ist die Ursache?','Warum wird die Bedingung nie falsch?',y,LE.filter(x=>x[1]!==y).map(x=>x[1]).concat(['Es liegt am Monitor. Der war schon immer komisch.']),y)});
S('schleife','l_off',()=>{const n=rint(4,9);return pick([()=>out('Der Plan: genau '+n+' Meldungen. Der Kollege schwört, das stimmt.',`int z = 0;\nfor (int i = 0; i <= ${n}; i++)\n{\n    z++;\n}\nConsole.WriteLine(z);`,'Was gibt das Programm aus?','Zähle auch die 0 und das letzte i mit.',n+1,`i läuft von 0 bis einschließlich ${n}. Das sind ${n+1} Durchläufe. Für genau ${n} braucht es i < ${n}.`),()=>code(`Die Schleife soll genau ${n}-mal laufen, läuft aber einmal zu oft.`,'Schreibe den korrigierten Schleifenkopf.','Start 0: Welcher Vergleich ergibt genau '+n+' Durchläufe?',[`for (int i = 0; i < ${n}; i++)`,`for (int i = 0; i <= ${n-1}; i++)`,`for (int i = 1; i <= ${n}; i++)`],`Von 0 bis ${n-1} sind es genau ${n} Durchläufe, also i < ${n}.`,'@@\n{\n}',{show:`for (int i = 0; i <= ${n}; i++)`})])()});
S('schleife','l_kopf',()=>{const n=rint(5,20);return code(`Die Zahlen von 1 bis ${n} sollen ausgegeben werden.`,'Schreibe den passenden Schleifenkopf.','Start, Bedingung, Schritt. Die Variable heißt i.',[`for (int i = 1; i <= ${n}; i++)`,`for (int i = 1; i < ${n+1}; i++)`,`for (int i = 1; i <= ${n}; i += 1)`,`for (int i = 1; i <= ${n}; ++i)`,`for (var i = 1; i <= ${n}; i++)`],`Start bei 1, weiter bis einschließlich ${n}, Schritt 1.`,'@@\n{\n    Console.WriteLine(i);\n}',{show:`____\n{\n    Console.WriteLine(i);\n}`})});

