S('methode','m_aufruf',()=>{const a=rint(2,9),b=rint(2,9);return out('Eine kleine Methode.',`static int Summe(int a, int b)\n{\n    return a + b;\n}\n\nConsole.WriteLine(Summe(${a}, ${b}));`,pre,'Was gibt die Methode zurück?',a+b,`Summe erhält ${a} und ${b} und gibt ${a+b} zurück.`)});
S('methode','m_param',()=>{const a=rint(2,9),b=rint(10,19);return out('Die Reihenfolge der Argumente entscheidet.',`static int Abzug(int gross, int klein)\n{\n    return gross - klein;\n}\n\nConsole.WriteLine(Abzug(${a}, ${b}));`,pre,'Welcher Wert landet in welchem Parameter?',a-b,`Das erste Argument landet im ersten Parameter: gross = ${a}, klein = ${b}. Der Name allein sortiert nichts.`)});
S('methode','m_return',()=>{const [h,a,y]=pick([['static int Doppelt(int x)\n{\n    x * 2;\n}',['return x * 2;'],'Der Wert muss mit return zurückgegeben werden.'],['static bool IstLeer(string s)\n{\n    s.Length == 0;\n}',['return s.Length == 0;'],'Der Vergleich liefert einen bool. return gibt ihn zurück.'],['static string Gruss(string n)\n{\n    "Hallo " + n;\n}',['return "Hallo " + n;'],'Der zusammengesetzte Text muss mit return zurückgegeben werden.']]);const sig=h.split('\n')[0];return code('Der Compiler beschwert sich über die mittlere Zeile.','Schreibe die korrigierte Zeile im Methodenrumpf.','Wie kommt der Wert aus der Methode heraus?',a,y,`${sig}\n{\n    @@\n}`,{show:h})});
S('methode','m_void',()=>{const [c,q,p,r,w,y]=pick([['static void Melde()\n{\n    Console.WriteLine("Hi");\n}\n\nint x = Melde();','Warum kompiliert das nicht?','Was bedeutet void?','Melde liefert keinen Wert, den man speichern könnte.',['int-Variablen dürfen nicht x heißen.','Melde fehlt ein Semikolon.','Methoden dürfen keinen Text ausgeben.'],'void heißt: kein Rückgabewert. Es gibt also nichts, was in x landen könnte.'],['static int Hole()\n{\n    Console.WriteLine(5);\n}','Warum kompiliert das nicht?','Was verspricht int vor dem Methodennamen?','Die Methode verspricht int, gibt aber nichts zurück.',['WriteLine darf nicht in Methoden stehen.','Methodennamen dürfen nicht mit H beginnen.','Es fehlt das Wort void hinter int.'],'Ausgeben ist nicht zurückgeben. Es fehlt ein return mit einem int.'],['static void Log(string t)\n{\n    return t;\n}','Warum kompiliert das nicht?','Darf eine void-Methode etwas zurückgeben?','Eine void-Methode darf keinen Wert zurückgeben.',['return ist bei string verboten.','Der Parameter muss int sein.','Methoden brauchen zwei Parameter.'],'void gibt nichts zurück. Für einen string müsste der Rückgabetyp string sein.']]);return choice('Eine Methode macht Ärger.',c,q,p,r,w,y)});
S('methode','m_scope',()=>{const n=rint(2,9);return choice('Eine Variable aus einem Block wird später gelesen.',`for (int i = 0; i < ${n}; i++)\n{\n    int letzter = i;\n}\nConsole.WriteLine(letzter);`,'Was passiert?','Wo lebt die Variable?','Fehler: letzter existiert nur innerhalb des Schleifenblocks.',[`Es wird ${n-1} ausgegeben.`,`Es wird ${n} ausgegeben.`,'Es wird 0 ausgegeben.'],'Eine Variable gilt nur in dem Block, in dem sie angelegt wurde. Sie müsste vor der Schleife deklariert werden.')});
S('methode','m_kopf',()=>{const [t,a,tpl,y]=pick([['Eine Methode IstAktiv bekommt einen int namens port und liefert wahr oder falsch.',['static bool IstAktiv(int port)'],'return port > 0;','Rückgabetyp bool, ein Parameter vom Typ int.'],['Eine Methode Melde bekommt einen string namens text und liefert nichts zurück.',['static void Melde(string text)'],'','Nichts zurückgeben heißt void.'],['Eine Methode Groesser bekommt zwei int namens a und b und liefert einen int.',['static int Groesser(int a, int b)'],'return a;','Rückgabetyp int, zwei Parameter, getrennt durch ein Komma.']]);return code(t,'Schreibe den Methodenkopf, also die Zeile vor der öffnenden Klammer.','static, Rückgabetyp, Name, Parameter.',a,y,`@@\n{\n    ${tpl}\n}`)});
S('methode','m_kopie',()=>{const a=rint(2,9);return out('Die Methode ändert ihren Parameter.',`static void Plus(int zahl)\n{\n    zahl += 10;\n}\n\nint wert = ${a};\nPlus(wert);\nConsole.WriteLine(wert);`,pre,'Bekommt die Methode das Original oder eine Kopie?',a,'Ein int wird als Kopie übergeben. Die Methode ändert nur ihre Kopie.')});
S('methode','m_kette',()=>{const a=rint(2,6);return out('Das Ergebnis eines Aufrufs geht in den nächsten.',`static int Doppelt(int x)\n{\n    return x * 2;\n}\n\nstatic int PlusEins(int x)\n{\n    return x + 1;\n}\n\nConsole.WriteLine(Doppelt(PlusEins(${a})));`,pre,'Was wird zuerst ausgewertet?',(a+1)*2,`Innen zuerst: PlusEins(${a}) = ${a+1}. Dann Doppelt(${a+1}) = ${(a+1)*2}.`)});

